import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Seite erstellen und bearbeiten","description":"Seiten anlegen, Blöcke einfügen, Struktur und Layout bearbeiten.","frontmatter":{"title":"Seite erstellen und bearbeiten","description":"Seiten anlegen, Blöcke einfügen, Struktur und Layout bearbeiten."},"headers":[],"relativePath":"seiten/seite-erstellen.md","filePath":"seiten/seite-erstellen.md","lastUpdated":1786434193000}'),a={name:"seiten/seite-erstellen.md"};function l(s,e,o,d,u,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="seite-erstellen-und-bearbeiten" tabindex="-1">Seite erstellen und bearbeiten <a class="header-anchor" href="#seite-erstellen-und-bearbeiten" aria-label="Permalink to &quot;Seite erstellen und bearbeiten&quot;">​</a></h1><h2 id="seite-anlegen" tabindex="-1">Seite anlegen <a class="header-anchor" href="#seite-anlegen" aria-label="Permalink to &quot;Seite anlegen&quot;">​</a></h2><ol><li>Öffnen Sie in der Seitenleiste den Bereich <strong>Seiten</strong>.</li><li>Klicken Sie auf <strong>Seite erstellen</strong>.</li><li>Vergeben Sie einen Titel.</li></ol><p>Die Seite ist zunächst leer.</p><h2 id="blocke-einfugen" tabindex="-1">Blöcke einfügen <a class="header-anchor" href="#blocke-einfugen" aria-label="Permalink to &quot;Blöcke einfügen&quot;">​</a></h2><p>Der Editor arbeitet wie ein Textdokument. Der Platzhalter lautet:</p><blockquote><p><em>Beginnen Sie zu tippen oder drücken Sie die Leertaste, um die Blockauswahl zu öffnen</em></p></blockquote><p>Zwei Wege:</p><ul><li><strong>Einfach tippen</strong> — der Text wird zu einem Absatz.</li><li><strong>Leertaste drücken</strong> — die Blockauswahl öffnet sich. Tippen Sie weiter, um zu filtern (<em>Zum Filtern tippen…</em>), und wählen Sie den Block aus.</li></ul><p>Die Auswahl ist in drei Gruppen unterteilt: <strong>Basis-Blöcke</strong>, <strong>Spezial-Blöcke</strong> und <strong>Formularfeld-Blöcke</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Schneller als die Maus</p><p>Die Leertaste am Zeilenanfang plus zwei, drei Buchstaben führt direkt zum gewünschten Block. „ta&quot; trifft das Tab-Layout, „sum&quot; die Summenkarte. Für längere Seiten ist das deutlich schneller als das Durchscrollen der Liste.</p></div><h2 id="der-strukturmodus" tabindex="-1">Der Strukturmodus <a class="header-anchor" href="#der-strukturmodus" aria-label="Permalink to &quot;Der Strukturmodus&quot;">​</a></h2><p>Über <strong>Strukturmodus anzeigen</strong> blenden Sie zwei zusätzliche Panels ein:</p><p><strong>Seitenstruktur</strong> — der Blockbaum. Hier sehen Sie die Verschachtelung, sortieren per Drag &amp; Drop um und fügen gezielt ein:</p><ul><li><strong>Block hinzufügen</strong> — innerhalb oder nach einem Block</li><li><strong>Tab hinzufügen</strong> — bei einem Tab-Layout</li><li><strong>Schritt hinzufügen</strong> — bei einem Stepper-Layout</li></ul><p><strong>Block Einstellungen</strong> — die Einstellungen des ausgewählten Blocks. Ohne Auswahl steht dort:</p><blockquote><p><em>Wählen Sie einen Block in der Struktur aus, um die Einstellungen zu sehen.</em></p></blockquote><p>Bei Blöcken ohne eigene Einstellungen erscheint:</p><blockquote><p><em>Für diesen Block gibt es noch kein eigenes Einstellungs-Panel.</em></p></blockquote><div class="tip custom-block"><p class="custom-block-title">Ab wann sich der Strukturmodus lohnt</p><p>Bei einfachen Textseiten brauchen Sie ihn nicht. Sobald Sie verschachtelte Layouts bauen — Layout im Layout, Tabs mit Unterseiten — ist er unverzichtbar: Im normalen Editor lässt sich schwer erkennen, welcher Block in welchem steckt.</p></div><h2 id="inhalt-oder-layout-bearbeiten" tabindex="-1">Inhalt oder Layout bearbeiten <a class="header-anchor" href="#inhalt-oder-layout-bearbeiten" aria-label="Permalink to &quot;Inhalt oder Layout bearbeiten&quot;">​</a></h2><p>Der Editor kennt zwei Bearbeitungsmodi:</p><ul><li><strong>Inhalt bearbeiten</strong> — Texte und Werte ändern</li><li><strong>Layout bearbeiten</strong> — Blöcke anordnen und verschachteln</li></ul><h2 id="seiteneinstellungen" tabindex="-1">Seiteneinstellungen <a class="header-anchor" href="#seiteneinstellungen" aria-label="Permalink to &quot;Seiteneinstellungen&quot;">​</a></h2><p>Über das Seitenmenü (<em>Seitenmenü öffnen</em>) erreichen Sie die Einstellungen der Seite, gegliedert in Abschnitte:</p><h3 id="seite" tabindex="-1">Seite <a class="header-anchor" href="#seite" aria-label="Permalink to &quot;Seite&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Einstellung</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>Icon &amp; Farbe festlegen</strong></td><td>Symbol und Farbe in der Navigation</td></tr><tr><td><strong>Cover-Bild hinzufügen</strong></td><td>Bild über der Seite</td></tr><tr><td><strong>Hintergrundfarbe festlegen</strong></td><td>Hintergrund der Seite</td></tr></tbody></table><h3 id="layout-darstellung" tabindex="-1">Layout &amp; Darstellung <a class="header-anchor" href="#layout-darstellung" aria-label="Permalink to &quot;Layout &amp; Darstellung&quot;">​</a></h3><p><strong>Seitenlayout festlegen</strong> mit drei Möglichkeiten:</p><table tabindex="0"><thead><tr><th>Layout</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Zentrierte Seite</strong></td><td>Inhalt in begrenzter Breite, zentriert</td></tr><tr><td><strong>Volle Breite</strong></td><td>Inhalt nutzt die gesamte Fensterbreite</td></tr><tr><td><strong>Kartenansicht</strong></td><td>Inhalt als abgesetzte Karte</td></tr></tbody></table><p>Der Hinweis <em>Gilt für die Anzeige im Portal</em> ist wichtig: Das Layout wirkt sich auf die veröffentlichte Seite aus, nicht auf den Editor.</p><p>Dazu <strong>Navigation einklappbar</strong> für Seiten mit Unterseiten.</p><h3 id="bearbeitung-zugriff" tabindex="-1">Bearbeitung &amp; Zugriff <a class="header-anchor" href="#bearbeitung-zugriff" aria-label="Permalink to &quot;Bearbeitung &amp; Zugriff&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Seite sperren</strong></td><td><em>Blocks sind nicht mehr bearbeitbar</em></td></tr><tr><td><strong>Richtiges Konto bestätigen</strong></td><td>Nutzer bestätigen vor dem Fortfahren ihre Identität</td></tr><tr><td><strong>Beim Laden automatisch absenden</strong></td><td><em>Sendet diese Seite automatisch beim Laden ab</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Seite sperren gegen versehentliche Änderungen</p><p>Sobald eine Seite produktiv genutzt wird, lohnt sich die Sperre. Sie verhindert, dass jemand beim Betrachten versehentlich einen Block verschiebt oder Text überschreibt.</p></div><div class="warning custom-block"><p class="custom-block-title">Automatisch absenden braucht vollständige Daten</p><p>Wie beim Formular gilt: Sendet sich die Seite beim Laden selbst ab, hat niemand Gelegenheit, Felder zu füllen. Sinnvoll ist das nur, wenn alle Werte über den Link vorbelegt sind — etwa um per QR-Code-Scan einen Flow zu starten.</p></div><h3 id="verwendung-in-flows" tabindex="-1">Verwendung in Flows <a class="header-anchor" href="#verwendung-in-flows" aria-label="Permalink to &quot;Verwendung in Flows&quot;">​</a></h3><p>Zeigt an, in welchen Flows diese Seite verwendet wird.</p><div class="tip custom-block"><p class="custom-block-title">Vor dem Löschen prüfen</p><p>Bevor Sie eine Seite löschen, sehen Sie hier nach. Wird sie von einem Flow-Schritt angezeigt, läuft dieser Flow danach in den Fehler <em>Für diesen Schritt ist keine eigene Oberfläche zugewiesen</em>.</p></div><h2 id="bedingte-sichtbarkeit" tabindex="-1">Bedingte Sichtbarkeit <a class="header-anchor" href="#bedingte-sichtbarkeit" aria-label="Permalink to &quot;Bedingte Sichtbarkeit&quot;">​</a></h2><p>Blöcke lassen sich abhängig von eingegebenen Werten ein- und ausblenden. Im Bereich <strong>Sichtbarkeit</strong> wählen Sie <strong>Feld</strong>, <strong>Bedingung</strong> und <strong>Wert</strong>.</p><p>Verfügbare Bedingungen: <em>ist leer</em>, <em>ist nicht leer</em>, <em>ist wahr</em>, <em>ist falsch</em>, <em>ist gleich</em>, <em>ist nicht gleich</em>, <em>ist größer als</em>, <em>ist kleiner als</em>.</p><p>Der Editor zeigt an, was gilt: <em>Sichtbar wenn {Bedingung}</em>, dazu <em>Aktuell sichtbar</em> beziehungsweise <em>Aktuell ausgeblendet</em>.</p><p>Für komplexere Fälle gibt es <strong>Erweitert (ApptiveScript)</strong> mit einem Ausdruck wie:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;age&#39;).greaterThan(18)</span></span></code></pre></div><p>→ <a href="/referenz/apptivescript-funktionen">ApptiveScript-Funktionen</a></p><div class="warning custom-block"><p class="custom-block-title">Nur im höchsten Tarif</p><p>Die bedingte Sichtbarkeit steht nur im Pro-Tarif zur Verfügung: <em>Upgraden Sie auf Pro, um Blöcke basierend auf Formularfeldwerten ein- oder auszublenden.</em></p></div><p>→ <a href="/seiten/sichtbarkeit">Bedingte Sichtbarkeit</a></p><h2 id="seite-umbenennen-und-loschen" tabindex="-1">Seite umbenennen und löschen <a class="header-anchor" href="#seite-umbenennen-und-loschen" aria-label="Permalink to &quot;Seite umbenennen und löschen&quot;">​</a></h2><p>Beides über das Seitenmenü. Das Löschen verlangt eine Bestätigung.</p><div class="danger custom-block"><p class="custom-block-title">Unterseiten verschwinden mit</p><p>Löschen Sie eine Seite, verschwinden auch ihre Unterseiten. Prüfen Sie vorher die Seitenstruktur — und ob ein veröffentlichter Portal-Link darauf zeigt.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/seiten/bloecke">Blockübersicht</a></li><li><a href="/seiten/layout-bloecke">Layout-Blöcke</a></li><li><a href="/seiten/portal-veroeffentlichen">Portal veröffentlichen</a></li></ul>',53)])])}const b=t(a,[["render",l]]);export{g as __pageData,b as default};
